[("blessing", 13560, 1)] = new("Forest Infusion", "Other build effects", "Within the area of [Spirit Summon], [Leaf Spirit] gains +50% attack speed and guaranteed Elemental Effect on hit. After summoning 250 [Leaf Spirit], Casting [Spirit Summon] fuses 3 [Leaf Spirit] in range into 1 [Forest Spirit]. [Forest Spirit] has 250% Attack Power and max HP of a [Leaf Spirit], receives all [Leaf Spirit] buffs, deals AoE with Normal attacks, and unlocks a new melee skill that deals Attack Power*200% damage"),
[("blessing", 13561, 1)] = new("Leaf Essence", "Other build effects", "Auto pick up seeds within 12m. +5% [Parasite] final DMG per pick up for 10s (max 200%). When [Parasite] stacks exceed the limit on an enemy, per excess stack instantly trigger 50% [Parasite] DMG"),
