[("blessing", 13564, 1)] = new("Vigour Immolation", "Other build effects", "Can cast [Enhanced Cloudbind Seal] when Vigour ≥ 60; casting consumes all Vigour, +0.5% final Weapon DMG per Vigour spent, lasts 12s; bonus increases by 200% when hitting enemies affected by [Shadowbind] from [Enhanced Cloudbind Seal]; if [Shadowbind] ends early, recover 5 Vigour per second remaining"),
[("blessing", 13565, 1)] = new("Shadow Merge", "Other build effects", "Each time [Shadowbind] is applied, Final Skill DMG +6% for 8s, up to 120% Every 4s, randomly applies [Shadowbind] to 3 unaffected enemies If Spiritual Blessing can't apply [Shadowbind] to enough enemies, restore 8 Vigour per missing target"),
[("blessing", 13567, 1)] = new("Corrosive Wither", "Other build effects", "+20% Corrosion DMG for 10s per Decay Effect triggered (max 200%). Every 4 triggers, deal imprison lasting 1s to enemy and gain 50% Movement Speed for 2s. Every 9 triggers, +1% final Corrosion DMG (max 80%, includes triggers before Spiritual Blessing)"),
